public class SeatRow
{
    private boolean[] booked;

    public SeatRow(int size)
    {
        booked = new boolean[size];
    }

    public int getSize()
    {
        return booked.length;
    }

    public boolean isBooked(int seat)
    {
        return booked[seat];
    }

    public boolean book(int seat)
    {
        if(seat < 0 || seat >= booked.length) {
            return false;
        }
        if(booked[seat]) {
            return false;
        }
        booked[seat] = true;
        return true;
    }

    public int countFree()
    {
        int free = 0;
        for(boolean taken : booked) {
            if(!taken) {
                free++;
            }
        }
        return free;
    }

    public int firstFree()
    {
        for(int seat = 0; seat < booked.length; seat++) {
            if(!booked[seat]) {
                return seat;
            }
        }
        return -1;
    }
}

