public class TemperatureLog
{
    public static final int HOURS = 24;
    private int[] readings;

    public TemperatureLog()
    {
        readings = new int[HOURS];
    }

    public boolean record(int hour, int degrees)
    {
        if(hour < 0 || hour >= readings.length) {
            return false;
        }
        readings[hour] = degrees;
        return true;
    }

    public int average()
    {
        int sum = 0;
        for(int degrees : readings) {
            sum += degrees;
        }
        return sum / readings.length;
    }

    public int warmestHour()
    {
        int best = 0;
        for(int hour = 1; hour < readings.length; hour++) {
            if(readings[hour] > readings[best]) {
                best = hour;
            }
        }
        return best;
    }

    public int hoursBelowZero()
    {
        int count = 0;
        for(int degrees : readings) {
            if(degrees < 0) {
                count++;
            }
        }
        return count;
    }
}

