public class GolfCard
{
    private static final int[] PAR = {4, 3, 5, 4, 4, 3, 4, 5, 4};
    private String player;
    private int[] strokes;

    public GolfCard(String player)
    {
        this.player = player;
        strokes = new int[PAR.length];
    }

    public String getPlayer()
    {
        return player;
    }

    public void record(int hole, int count)
    {
        if(hole >= 0 && hole < strokes.length) {
            strokes[hole] = count;
        }
    }

    public int total()
    {
        int sum = 0;
        for(int count : strokes) {
            sum += count;
        }
        return sum;
    }

    public int holesUnderPar()
    {
        int count = 0;
        for(int hole = 0; hole < strokes.length; hole++) {
            if(strokes[hole] < PAR[hole]) {
                count++;
            }
        }
        return count;
    }

    public int bestHole()
    {
        int best = 0;
        for(int hole = 1; hole < strokes.length; hole++) {
            if(strokes[hole] - PAR[hole] < strokes[best] - PAR[best]) {
                best = hole;
            }
        }
        return best;
    }
}
